:root {
  --text-title-color: #246875;
  --text-scale: 1;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;

  border: none;
  background: transparent !important;
}

.text-widget,
.text-widget * {
  box-sizing: border-box;
}

.text-widget {
  position: relative;

  width: 100%;
  height: 100%;
  overflow: hidden;

  background: transparent;
  pointer-events: none;

  font-family:
    "Bahnschrift",
    "DIN Alternate",
    Consolas,
    "Liberation Mono",
    monospace;

  font-style: normal;
  font-variant-ligatures: none;
}

.text-layout {
  position: absolute;
  left: 50%;
  top: 50%;

  width: 312px;
  height: 44px;

  background: transparent;

  transform:
    translate(-50%, -50%)
    scale(var(--text-scale));

  transform-origin: center;
}

.text-heading {
  position: absolute;
  left: 18px;
  top: 0;

  display: flex;
  align-items: center;
  justify-content: center;

  width: 276px;
  height: 44px;

  overflow: hidden;
  background: transparent;
}

.text-title {
  display: block;
  flex: 0 0 auto;

  color: var(--text-title-color);
  font-size: 20px;
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: 0;

  white-space: nowrap;
  text-align: center;
}

js:
"use strict";

(function () {
  const DEFAULT_TITLE = "Pre-estiramiento";

  const DESIGN_WIDTH = 312;
  const DESIGN_HEIGHT = 44;
  const BASE_TITLE_SIZE = 20;
  const MAX_TITLE_WIDTH = 276;

  let container = null;
  let titleElement = null;
  let latestWidget = null;
  let resizeObserver = null;

  function fitTitle() {
    if (!titleElement) return;

    titleElement.style.fontSize =
      BASE_TITLE_SIZE + "px";

    const textWidth = titleElement.scrollWidth;

    if (textWidth > MAX_TITLE_WIDTH) {
      titleElement.style.fontSize =
        (BASE_TITLE_SIZE * MAX_TITLE_WIDTH / textWidth) + "px";
    }
  }

  function resizeLayout() {
    if (!container) return;

    const width = container.clientWidth;
    const height = container.clientHeight;

    if (width <= 0 || height <= 0) return;

    const scale = Math.min(
      width / DESIGN_WIDTH,
      height / DESIGN_HEIGHT
    );

    container.style.setProperty(
      "--text-scale",
      String(scale)
    );

    fitTitle();
  }

  function render(w) {
    if (!titleElement) return;

    const name =
      w && typeof w.name === "string"
        ? w.name.trim()
        : "";

    titleElement.textContent = name || DEFAULT_TITLE;

    fitTitle();
  }

  /*
   * El texto corresponde al Nombre del inspector.
   * No utiliza variables del PLC.
   */
  window.onWidgetUpdate = function (w) {
    latestWidget = w;
    render(w);
  };

  function initialize() {
    container = document.querySelector(".text-widget");
    titleElement = document.querySelector(".text-title");

    if (!container || !titleElement) return;

    render(latestWidget || window.WIDGET || null);
    resizeLayout();

    requestAnimationFrame(fitTitle);

    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(fitTitle);
    }

    if (typeof ResizeObserver !== "undefined") {
      resizeObserver = new ResizeObserver(resizeLayout);
      resizeObserver.observe(container);
    } else {
      window.addEventListener("resize", resizeLayout);
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
